cd /tmp && mkdir -p gt && cat > gt/t.mjs <<'EOF'
import assert from 'node:assert';
import { execFileSync, spawn } from 'node:child_process';
const [,, botPath] = process.argv;
const { recordEvent: rec, checkEmail: chk } = await import(botPath);
const now = new Date();
const c = (email, kind) => chk({ email, kind, now });
assert.deepEqual(await c('<EMAIL>','marketing'), {allowed:true, rule:''});
await rec({ email:'  Jane.Doe+x@Example.COM ', type:'unsubscribe', now });
for (const e of ['jane.doe@example.com','"J" <JANE.DOE@example.com>','mailto:jane.doe+y@EXAMPLE.com.'])
  assert.equal((await c(e,'marketing')).allowed,false, e);
assert.equal((await c('jane.doe@example.com','transactional')).allowed,true);
await rec({ email:'<EMAIL>', type:'spam_complaint', now });
assert.equal((await c('<EMAIL>','marketing')).rule,'spam_complaint');
assert.equal((await c('<EMAIL>','transactional')).allowed,true);
await rec({ email:'gone@bücher.de', type:'hard_bounce', now });
assert.equal((await c('<EMAIL>','transactional')).rule,'hard_bounce');
assert.equal((await c('nope','marketing')).rule,'invalid_address');
assert.equal((await c('<EMAIL>','x')).rule,'invalid_kind');
// concurrency: 8 processes, same + different addresses
const procs = [...Array(8)].map((_, i) => new Promise((res, rej) => {
  const p = spawn(process.execPath, ['-e', `import(${JSON.stringify(botPath)}).then(async m=>{await Promise.all([...Array(25)].map((_,j)=>m.recordEvent({email:'u'+j+'@race.com',type:'unsubscribe',now:new Date()})))})`], {stdio:'inherit'});
  p.on('exit', c => c ? rej(new Error('exit '+c)) : res());
}));
await Promise.all(procs);
for (let j=0;j<25;j++) assert.equal((await c('u'+j+'@race.com','marketing')).allowed,false);
console.log('ok');
EOF
